let counter = std::sync::Mutex::new(0);
let mut guard = counter.lock().unwrap();
*guard += 1;
drop(guard);
match counter.lock() {
    Ok(g) => println!("Value: {}", *g),
    Err(_) => println!("Poisoned"),
}
```

